<h1 class="page-title">Đơn hàng <?= e($order['code']) ?></h1><div class="row"><div class="col-lg-8"><div class="panel"><span class="status <?= e($order['status']) ?>"><?= e(status_label($order['status'])) ?></span><p class="muted mt-3">Ngày đặt: <?= e($order['created_at']) ?></p><table class="table"><thead><tr><th>Sản phẩm</th><th>Số lượng</th><th>Thành tiền</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?= e($item['product_name']) ?><small class="d-block muted"><?= e($item['sku']) ?></small></td><td><?= $item['quantity'] ?></td><td><?= money((int)$item['unit_price']*$item['quantity']) ?></td></tr><?php endforeach?></tbody></table><h2 class="text-end"><?= money($order['total']) ?></h2></div><div class="panel"><h2>Lịch sử trạng thái</h2><?php foreach($history as $h):?><p class="border-bottom py-3"><b><?= e(status_label($h['to_status'])) ?></b><small class="d-block muted mt-1"><?= e($h['created_at']) ?> · <?= e($h['note']) ?></small></p><?php endforeach?></div></div><div class="col-lg-4"><div class="panel"><h2>Thông tin giao nhận</h2><p class="lh-lg"><?= e($order['recipient']) ?><br><?= e($order['phone']) ?><br><?= e($order['address_line']) ?></p><p class="muted"><?= e($order['note']) ?></p><h3>Thanh toán</h3><p><?= $order['payment_method']==='cod'?'Thanh toán khi nhận hàng':'Chuyển khoản' ?></p><?php if(!$payments):?><span class="status">Chưa thanh toán</span><?php endif?><?php foreach($payments as $payment):?><p><?= e(status_label($payment['status'])) ?>: <?= money($payment['amount']) ?></p><?php endforeach?></div></div></div>
